Future<void> measure() async {
  final locals = _MeasureLocals();

  try {
    ts.eval(
      'Locals.Measurement_Names=Split(FileGlobals.Current_Sweep_Step.Input_and_Output.PARAMS.Test_Config,",")',
    ); // Split Test Names into Array

    // If DPD enabled
    if (currentSweepStep.Input_and_Output.PARAMS.DPD_Enabled == true) {
      await ts.callVi(
        'SpecAn\\mx\\RFmxSpecAn.llb\\RFmxSpecAn Select Measurement (Single).vi',
        inputs: {
          'Selector String': configurations.Analyzer.RFmxSpecAn_Selector_String,
          'Instrument Handle In': deviceHandles.RFmx,
          'Measurement': 11,
        },
      ); // Select Single DPD Measurement
      final outputs = await ts.callVi(
        '..\\..\\Source\\Methods\\RFmxDPD\\Measurements\\Perform Memory Polynomial.vi',
        inputs: {
          'Selector String': configurations.Analyzer.RFmxSpecAn_Selector_String,
          'RFmx Instrument Handle In': deviceHandles.RFmx,
          'RFSG Instrument Handle In': deviceHandles.RFSG,
          'Reference Waveform': currentSweepStep.Loaded_Waveform,
          ' Memory Polynomial Configuration': configurations.Analyzer.SpecAn_DPD.DPD_Memory_Polynomial_Configuration,
        },
      ); // DPD Perform Memory Polynomial
      deviceHandles.RFmx = outputs['RFmx Instrument Handle Out'];
      deviceHandles.RFSG = outputs['RFSG Instrument Handle Out'];
    }
    for (final element in ts.iterate(locals.measurementNames)) {
      locals.currentMeasurement = element as String;
      // Select the appropriate action based on which measurement is selected
      {
        final select1 = locals.currentMeasurement;
        var matched1 = false;
        // AMPM Method
        if (!matched1 && select1 == 'AMPM') {
          matched1 = true;
          await ts.callVi(
            '..\\..\\Source\\SA\\RFmxSpecAn\\Measurements\\SpecAn Select and Initiate Measurements.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmxSpecAn_Selector_String,
              'Instrument Handle In': deviceHandles.RFmx,
              'Measurements.[0]': 10,
              'Auto Level Configuration': configurations.Analyzer.Auto_Level_Configuration,
              'Auto Level Bandwidth (Hz)': 400000000,
            },
          ); // Select and Initiate SpecAn AMPM Measurement
          currentSweepStep.Results.SpecAn_AMPM_Results = (await ts.callVi(
            '..\\..\\Source\\SA\\RFmxSpecAn\\Measurements\\SpecAn Fetch AMPM.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmxSpecAn_Selector_String,
              'RFmx Handle In': deviceHandles.RFmx,
            },
          ))['AMPM Results']; // SpecAn Fetch AMPM
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_LinerGain_dB =
              currentSweepStep.Results.SpecAn_AMPM_Results.Mean_Linear_Gain__dB_; // Map Results
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_RMS_EVM =
              currentSweepStep.Results.SpecAn_AMPM_Results.Mean_RMS_EVM____;
        }
        // Adjacent Channel Power Measurement
        if (!matched1 && select1 == 'ACP') {
          matched1 = true;
          await ts.callVi(
            '..\\..\\Source\\SA\\RFmxNR\\Measurements\\NR Select and Initiate Measurements.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmx_Selector_String,
              'Instrument Handle In': deviceHandles.RFmx,
              'Measurements.[0]': 2,
              'Auto Level Configuration': configurations.Analyzer.Auto_Level_Configuration,
            },
          ); // Select and Initiate NR ACP Measurement
          currentSweepStep.Results.NR_ACP_Results = (await ts.callVi(
            '..\\..\\Source\\SA\\RFmxNR\\Measurements\\NR Fetch ACP.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmx_Selector_String,
              'RFmx Handle In': deviceHandles.RFmx,
            },
          ))['ACP Results']; // NR Fetch ACP
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.ACP_CC0_Absolute_Power_dBm =
              currentSweepStep.Results.NR_ACP_Results.Component_Carrier_Results[0].Absolute_Power__dBm_; // Map Results
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Upper_Absolute_Power_dBm =
              currentSweepStep.Results.NR_ACP_Results.Offset_Results[0].Upper_Absolute_Power__dBm_;
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Upper_Relative_Power_dB =
              currentSweepStep.Results.NR_ACP_Results.Offset_Results[0].Upper_Relative_Power__dB_;
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Lower_Absolute_Power_dBm =
              currentSweepStep.Results.NR_ACP_Results.Offset_Results[0].Lower_Absolute_Power__dBm_;
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Lower_Relative_Power_dB =
              currentSweepStep.Results.NR_ACP_Results.Offset_Results[0].Lower_Relative_Power__dB_;
        }
        // EVM Measurement
        if (!matched1 && select1 == 'EVM') {
          matched1 = true;
          await ts.callVi(
            '..\\..\\Source\\SA\\RFmxNR\\Measurements\\NR Select and Initiate Measurements.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmx_Selector_String,
              'Instrument Handle In': deviceHandles.RFmx,
              'Measurements.[0]': 0,
              'Auto Level Configuration': configurations.Analyzer.Auto_Level_Configuration,
            },
          ); // Select and Initiate NR ModAcc Measurement
          currentSweepStep.Results.NR_ModAcc_Results = (await ts.callVi(
            '..\\..\\Source\\SA\\RFmxNR\\Measurements\\NR Fetch ModAcc.vi',
            inputs: {
              'Selector String': configurations.Analyzer.RFmx_Selector_String,
              'RFmx Handle In': deviceHandles.RFmx,
            },
          ))['ModAcc Results']; // NR Fetch ModAcc
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.RMS_Composite_EVM_Percent = currentSweepStep
              .Results
              .NR_ModAcc_Results
              .Component_Carrier_Results[0]
              .Mean_RMS_Composite_EVM; // Map Results
        }
      }
    }
  } finally {
    await ts.callVi(
      '..\\..\\Source\\SG\\Abort Generation.vi',
      inputs: {'RFSG handle': deviceHandles.RFSG},
    ); // Abort Dynamic Generation
  }
}

Future<void> sequenceFileLoad() async {
  await ts.messagePopup(
    'First Launch Message',
    'If this is your first time opening this example sequence, please make sure to check the following:\n\n- To use the proper RF devices, in the Variable pane navigate to FileGlobals.Static_Station_Configs.Device_Names \n  and enter the device identifiers there. \n\n- When using a PXIe 5830/31 enter the respective portnames in FileGlobals.Configurations.Analyzer.Common_Config.SelectedPorts and in\n  FileGlobals.Configurations.Generator.RFSGConfig.SelectedPorts.\n\n- You can change the waveform configuration under FileGlobals.Static_Station_Configs.Waveform_Configs. \n\n- All other Analyzer and Generator configurations can be found in the Configurations Container.\n\n- The sequence will write a CSV result file in <./DataFiles/Results/>. You can change the parameters and measurements written to the file in \n  FileGlobals.Current_Sweep_Step.Input_and_Output and by adapting the \'Map Results\' expression step in the Measure subsequence.\n\nFeel free to keep this message from appearing next time you load the sequence by removing the \'SequenceFileLoad\' callback from the Sequences pane.',
  );
}
